#!/usr/bin/env python3
"""Build the SCR-LIP pilot registry from curated claims.
Empirical claims (Amato's published studies + external evidence) go into claims.json.
The IIT2/gfWAT theory claims are HELD OUT (per author) in _held_out_theory.json.
Also emits claims.csv (flattened) for spreadsheet review.
"""
import json, csv, os

DIR = os.path.dirname(os.path.abspath(__file__))
COMMON = {"curators": [{"name": "Alexandre C. M. Amato", "orcid": "0000-0003-4008-4029", "role": "lead_curator"}],
          "created": "2026-05-30", "updated": "2026-05-30", "license": "CC-BY-4.0", "registry_version": "0.1"}

def C(statement, statement_pt, claim_type, context, ks, ec, evidence, relations, gaps, src):
    return {"statement": statement, "statement_pt": statement_pt, "claim_type": claim_type,
            "context": context, "knowledge_state": ks, "evidence_confidence": ec,
            "evidence": evidence, "relations": relations, "gaps": gaps, "primary_amato_source": src}

def ev(ref, stance, design, n, rob, year, amato, note=""):
    return {"ref": ref, "stance": stance, "study_design": design, "n": n, "risk_of_bias": rob,
            "year": year, "amato_authored": amato, "note": note}

def ctx(pop, exp, comp, out, scope):
    return {"population": pop, "condition": "lipedema", "exposure": exp, "comparator": comp, "outcome": out, "scope": scope}

