# assign IDs + metadata
for i, c in enumerate(claims, 1):
    c["id"] = f"SCR-LIP-{i:06d}"
    c.update(COMMON)
# reorder id first
ordered = [{**{"id": c["id"]}, **{k: v for k, v in c.items() if k != "id"}} for c in claims]

with open(os.path.join(DIR, "claims.json"), "w") as f:
    json.dump({"registry":"SCR-LIP","version":"0.1","date":"2026-05-30","count":len(ordered),"claims":ordered}, f, ensure_ascii=False, indent=2)

with open(os.path.join(DIR, "_held_out_theory.json"), "w") as f:
    json.dump({"note":"Author's IIT2/gfWAT theory — intentionally NOT in the registry yet (per author, 2026-05-30). Staged for future inclusion once empirically supported.","count":len(held),"items":held}, f, ensure_ascii=False, indent=2)

# CSV (flattened)
with open(os.path.join(DIR, "claims.csv"), "w", newline="") as f:
    w = csv.writer(f)
    w.writerow(["id","claim_type","knowledge_state","evidence_confidence","statement","primary_amato_source","n_evidence","amato_evidence","gaps"])
    for c in ordered:
        amato_n = sum(1 for e in c["evidence"] if e.get("amato_authored"))
        w.writerow([c["id"], c["claim_type"], c["knowledge_state"], c["evidence_confidence"], c["statement"],
                    c["primary_amato_source"], len(c["evidence"]), amato_n, c["gaps"]])

print(f"Registry claims: {len(ordered)}")
print(f"Held-out theory items: {len(held)}")
from collections import Counter
print("by knowledge_state:", dict(Counter(c["knowledge_state"] for c in ordered)))
